/// Get the state directory for a project.
///
/// Uses platform-appropriate data directory:
/// - Linux: `~/.local/share/bivvy/projects/{hash}`
/// - macOS: `~/Library/Application Support/bivvy/projects/{hash}`
/// - Windows: `{FOLDERID_LocalAppData}/bivvy/projects/{hash}`
pub fn state_dir(project_id: &ProjectId) -> PathBuf {
    dirs::data_local_dir()
        .unwrap_or_else(|| PathBuf::from("."))
        .join("bivvy")
        .join("projects")
        .join(project_id.hash())

